SELECT 
FROM resume_application ra
WHERE ra.id = #{id}

SELECT , jp.title AS job_title, jp.city_name, jp.company_id, hc.name AS company_name, hc.logo_url AS company_logo, su.name AS candidate_name FROM resume_application ra INNER JOIN job_post jp ON ra.job_id = jp.id LEFT JOIN hr_company hc ON jp.company_id = hc.id LEFT JOIN sys_user su ON ra.candidate_id = su.id WHERE jp.company_id = #{companyId}
AND ra.id IN
#{id}
AND ra.status = #{status} AND ra.job_id = #{jobId} AND ra.match_score >= #{minMatchScore}
AND su.name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY ra.submitted_at DESC
ORDER BY ra.match_score DESC

